import{_ as e,c as s,o as t,ag as n}from"./chunks/framework.DZ_cNctr.js";const k=JSON.parse('{"title":"Data Server","description":"Host your own OME-Zarr data server on your lab network with Docker. The browser streams chunks straight from your infrastructure, so the data stays on it.","frontmatter":{"title":"Data Server","description":"Host your own OME-Zarr data server on your lab network with Docker. The browser streams chunks straight from your infrastructure, so the data stays on it."},"headers":[],"relativePath":"guides/data-server.md","filePath":"guides/data-server.md"}'),i={name:"guides/data-server.md"};function r(o,a,l,h,d,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="data-server" tabindex="-1">Data Server <a class="header-anchor" href="#data-server" aria-label="Permalink to &quot;Data Server&quot;">​</a></h1><p><a href="https://hub.docker.com/r/fn0000/fn-data-server" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/Docker%20Hub-fn0000%2Ffn--data--server-blue?logo=docker" alt="Docker Hub"></a></p><p>Host your own OME-ZARR data server on your lab network. Your data never leaves your infrastructure. The browser streams ZARR chunks directly from your server.</p><h2 id="why-use-a-data-server" tabindex="-1">Why Use a Data Server? <a class="header-anchor" href="#why-use-a-data-server" aria-label="Permalink to &quot;Why Use a Data Server?&quot;">​</a></h2><ul><li><strong>Keep data on-site</strong>: no cloud upload, no transfer costs</li><li><strong>Access control</strong>: JWT tokens scoped to specific datasets</li><li><strong>Works with the viewer</strong>: just paste a URL and go</li><li><strong>Simple setup</strong>: one Docker command</li></ul><div class="tip custom-block"><p class="custom-block-title">The whole progression</p><p><a href="https://www.find-nuclei.com/blog/share-zarr-with-your-team" target="_blank" rel="noreferrer">Share Your Microscopy Data With Your Team Without Sending Anyone a Hard Drive</a> walks it end to end: open a local file, put it behind this server for colleagues on the network, then add a token once the data is sensitive. It also covers when you do not need this server at all, which is any time the data already sits on S3 or MinIO.</p></div><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.findnuclei</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3333:3333</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3334:3334</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/your/zarr/data:/data/storage</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.findnuclei:/data/config</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FN_ADMIN_PASSWORD=changeme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  fn0000/fn-data-server</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Port</th><th>What</th></tr></thead><tbody><tr><td><strong>3333</strong></td><td>Data server. S3-compatible, serves ZARR chunks</td></tr><tr><td><strong>3334</strong></td><td>Admin console. Manage tokens, browse buckets</td></tr></tbody></table><p>Two mount points:</p><ul><li><strong><code>/data/storage</code></strong>: your ZARR data directory (read-only is fine)</li><li><strong><code>/data/config</code></strong>: token database and signing key (persists across restarts)</li></ul><h2 id="organize-your-data" tabindex="-1">Organize Your Data <a class="header-anchor" href="#organize-your-data" aria-label="Permalink to &quot;Organize Your Data&quot;">​</a></h2><p>Each top-level directory in your storage becomes a <strong>bucket</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/your/zarr/data/</span></span>
<span class="line"><span>├── project-alpha/</span></span>
<span class="line"><span>│   ├── sample1.zarr/</span></span>
<span class="line"><span>│   └── sample2.zarr/</span></span>
<span class="line"><span>└── project-beta/</span></span>
<span class="line"><span>    └── experiment.zarr/</span></span></code></pre></div><h2 id="view-your-data" tabindex="-1">View Your Data <a class="header-anchor" href="#view-your-data" aria-label="Permalink to &quot;View Your Data&quot;">​</a></h2><p>Once the server is running, open the viewer with a direct link:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://find-nuclei.github.io?url=http://localhost:3333/project-alpha/sample1.zarr</span></span></code></pre></div><p>Or paste the URL into the <strong>Open Image</strong> dialog.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>By default, the data server requires JWT tokens for all data access. This is the recommended mode for any network that isn&#39;t fully trusted.</p><h3 id="create-a-token" tabindex="-1">Create a Token <a class="header-anchor" href="#create-a-token" aria-label="Permalink to &quot;Create a Token&quot;">​</a></h3><ol><li>Open the admin console at <code>http://localhost:3334/admin</code></li><li>Log in with your admin password</li><li>Set a <strong>label</strong> (e.g., &quot;Alice&#39;s token&quot;) and <strong>scope</strong> (bucket name or <code>*</code> for all)</li><li>Click <strong>Create Token</strong></li><li>Copy the token. It won&#39;t be shown again</li></ol><h3 id="use-the-token-in-the-viewer" tabindex="-1">Use the Token in the Viewer <a class="header-anchor" href="#use-the-token-in-the-viewer" aria-label="Permalink to &quot;Use the Token in the Viewer&quot;">​</a></h3><p><strong>Option 1: URL parameter</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://find-nuclei.github.io?url=http://localhost:3333/project-alpha/sample.zarr&amp;token=YOUR_JWT</span></span></code></pre></div><p><strong>Option 2: Auth prompt</strong></p><p>If you open a URL without a token, the viewer detects the 401 response and shows a 🔑 token prompt. Paste your token and the image loads.</p><h3 id="token-scoping" tabindex="-1">Token Scoping <a class="header-anchor" href="#token-scoping" aria-label="Permalink to &quot;Token Scoping&quot;">​</a></h3><p>Tokens can be restricted to specific buckets:</p><ul><li><strong><code>project-alpha</code></strong>: only access <code>/project-alpha/</code> and its contents</li><li><strong><code>*</code></strong>: wildcard, access everything</li></ul><p>Additional restrictions (optional):</p><ul><li><strong>TTL</strong>: token expires after a set time</li><li><strong>Host</strong>: only works from specific domains (supports wildcards: <code>*.lab.internal</code>)</li><li><strong>IP</strong>: only works from specific client IPs (supports wildcards: <code>192.168.1.*</code>)</li></ul><h2 id="open-mode" tabindex="-1">Open Mode <a class="header-anchor" href="#open-mode" aria-label="Permalink to &quot;Open Mode&quot;">​</a></h2><p>For fully trusted networks (isolated lab VLAN, localhost only), you can disable authentication:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FN_AUTH_ENABLED=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  fn0000/fn-data-server</span></span></code></pre></div><p>All data endpoints are open. No tokens needed.</p><h2 id="scaling" tabindex="-1">Scaling <a class="header-anchor" href="#scaling" aria-label="Permalink to &quot;Scaling&quot;">​</a></h2><p>The data server runs multiple worker processes by default:</p><table tabindex="0"><thead><tr><th>Users</th><th>Config</th></tr></thead><tbody><tr><td>1–5</td><td>Default (4 workers)</td></tr><tr><td>5–20</td><td><code>-e FN_DATA_WORKERS=8</code></td></tr><tr><td>20–50</td><td>Multiple containers behind a load balancer</td></tr></tbody></table><h2 id="network-setup" tabindex="-1">Network Setup <a class="header-anchor" href="#network-setup" aria-label="Permalink to &quot;Network Setup&quot;">​</a></h2><p>The data server only needs to be reachable from the user&#39;s <strong>browser</strong>, not from the internet:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┐          ┌─────────────┐          ┌──────────────┐</span></span>
<span class="line"><span>│  Viewer     │  ZARR    │   User&#39;s    │  ZARR    │ Data Server  │</span></span>
<span class="line"><span>│  (github.io)│  metadata│   Browser   │  chunks  │ (your LAN)   │</span></span>
<span class="line"><span>│             │◄────────►│             │◄────────►│              │</span></span>
<span class="line"><span>└─────────────┘          └─────────────┘          └──────────────┘</span></span></code></pre></div><p>Common setups:</p><ul><li><strong>Localhost</strong>: viewer and data server on the same machine</li><li><strong>Lab network</strong>: data server on a NAS or shared workstation</li><li><strong>VPN</strong>: users connect to the lab network remotely</li></ul><h3 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h3><p>The data server allows all origins by default (<code>FN_CORS_ORIGINS=*</code>). To restrict:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FN_CORS_ORIGINS=https://find-nuclei.github.io,http://localhost:8080</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="image-loads-but-appears-dark" tabindex="-1">Image loads but appears dark <a class="header-anchor" href="#image-loads-but-appears-dark" aria-label="Permalink to &quot;Image loads but appears dark&quot;">​</a></h3><p>Auto-contrast needs pixel data to calculate display range. Try adjusting the channel contrast sliders manually, or click the auto-contrast button after the image has loaded.</p><h3 id="_401-403-errors" tabindex="-1">401 / 403 errors <a class="header-anchor" href="#_401-403-errors" aria-label="Permalink to &quot;401 / 403 errors&quot;">​</a></h3><ul><li><strong>401</strong>: no token provided. Add <code>&amp;token=YOUR_JWT</code> to the URL or enter it in the auth prompt.</li><li><strong>403</strong>: token is invalid, expired, or scoped to a different bucket. Create a new token in the admin console.</li></ul><h3 id="can-t-connect-from-browser" tabindex="-1">Can&#39;t connect from browser <a class="header-anchor" href="#can-t-connect-from-browser" aria-label="Permalink to &quot;Can&#39;t connect from browser&quot;">​</a></h3><ul><li>Check that the data server is reachable from your browser (not just the server machine)</li><li>If using Docker Desktop on Mac/Windows, <code>localhost</code> works from the host but not from other machines on the network. Use the machine&#39;s LAN IP instead.</li><li>Check CORS settings if you see network errors in the browser console.</li></ul><h3 id="docker-networking" tabindex="-1">Docker networking <a class="header-anchor" href="#docker-networking" aria-label="Permalink to &quot;Docker networking&quot;">​</a></h3><p>In Docker, the client IP seen by the server is the Docker gateway (e.g., <code>192.168.65.1</code>), not <code>127.0.0.1</code>. Check <code>http://localhost:3334/health</code>. The <code>your_ip</code> field shows what IP the server sees for your requests.</p>`,56)])])}const u=e(i,[["render",r]]);export{k as __pageData,u as default};
